mapper.select:
SELECT c.course_id AS courseId, c.course_code AS courseCode, c.course_name AS courseName, c.credit AS credit, c.course_hours AS courseHours, c.course_type AS courseType, c.teacher_id AS teacherId, t.teacher_name AS teacherName, c.semester AS semester, c.course_status AS courseStatus, c.course_remark AS courseRemark, c.gmt_create AS gmtCreate, c.gmt_modified AS gmtModified FROM edu_course c LEFT JOIN edu_teacher t ON c.teacher_id = t.teacher_id AND t.teacher_deleted = 0 WHERE c.course_deleted = 0
AND c.course_code LIKE CONCAT('%', #{courseCode}, '%')
AND c.course_name LIKE CONCAT('%', #{courseName}, '%')
AND c.course_type = #{courseType}
AND c.teacher_id = #{teacherId}
AND c.semester = #{semester}
AND c.course_status = #{courseStatus}
ORDER BY c.course_code
